+                "dapr-component" => scope.Kind == "namespace",
+                "container-runtime" or "node-os" => scope.Kind == "node",
+                "crd" or "kubernetes" => scope.Kind == "cluster",
+                "rancher" or "operator" => scope.Kind is "cluster" or "namespace",
