+            v1.Applications, v1.Components.Select(ProductionProfileValidationComponent.From).ToArray(),
+            v1.Catalogs, v1.Protection, v1.Issuer, v1.Freshness, v1.Restore, v1.Evidence, v1.InfrastructureDigest),
